#else
  #ifndef USE_PBR_TRANSPARENCY
    _output.color *= _surface.transparent.a;
  #endif
#endif
    
#else 
    
#ifdef USE_TRANSPARENCY 
  #ifndef USE_PBR_TRANSPARENCY
    _output.color *= scn_commonprofile.transparency;
  #endif
#endif
    
#endif 
    
#ifdef USE_NODE_OPACITY
    _output.color *= in.nodeOpacity;
